    primaryMetric: PairedAblationFixture['preregistration']['primaryMetric'];
    effect: EffectEstimate;
    successEffect: EffectEstimate;
    latencyEffect: EffectEstimate;
    tokensEffect: EffectEstimate;
    falseInterceptions: { baseline: number; treatment: number; difference: number };
    safetyViolations: { baseline: number; treatment: number; difference: number };
  };
  componentChanged: boolean;
  preregistration: PairedAblationFixture['preregistration'];
  decision: string;
}

export function runPairedAblation(options: PairedAblationOptions): Promise<PairedAblationReport>;
export function loadFixture(path?: URL | string): Promise<PairedAblationFixture>;
export const metrics: {
  conditionSummary(runs: Array<{
    caseId: string;
    success: boolean;
    latencyMs: number;
    tokensProxy: number;
    falseInterception: boolean;
    safetyViolation: boolean;
  }>): ConditionSummary;
  effect(differences: number[]): EffectEstimate;
  passK(groups: boolean[][], k: number): number | null;
  quantile(values: number[], p: number): number | null;
  tokenProxy(text: string): number;
};
