const DEFAULT_FIXTURE = new URL('../../shared/agent-dev/paired-ablation-fixture.json', import.meta.url);
const CONDITIONS = Object.freeze(['baseline', 'treatment']);
const ALPHABET = '0123456789abcdefghijklmnopqrstuvwxyz';

function assert(condition, message) {
  if (!condition) throw new Error(message);
}

function quantile(values, p) {
  if (values.length === 0) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const index = (sorted.length - 1) * p;
  const lower = Math.floor(index);
  const upper = Math.ceil(index);
  if (lower === upper) return sorted[lower];
  return sorted[lower] + (sorted[upper] - sorted[lower]) * (index - lower);
}

function mean(values) {
  return values.length === 0 ? null : values.reduce((sum, value) => sum + value, 0) / values.length;
}

function round(value, digits = 6) {
  if (value === null || !Number.isFinite(value)) return null;
  const factor = 10 ** digits;
  return Math.round((value + Number.EPSILON) * factor) / factor;
}

function tokenProxy(text) {
  // E01-compatible local proxy: Unicode word pieces plus punctuation pieces.
  const matches = String(text ?? '').match(/[\p{L}\p{N}_]+|[^\s\p{L}\p{N}_]/gu);
  return matches ? matches.length : 0;
}

function pairedBootstrap(differences, iterations, seed) {
  if (differences.length === 0) return { low: null, high: null };
  let state = seed >>> 0;
  const sums = new Array(iterations).fill(0);
  for (let iteration = 0; iteration < iterations; iteration += 1) {
    let total = 0;
    for (let sample = 0; sample < differences.length; sample += 1) {
      state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
      total += differences[state % differences.length];
    }
    sums[iteration] = total / differences.length;
  }
  return { low: quantile(sums, 0.025), high: quantile(sums, 0.975) };
}

function effect(differences) {
  const average = mean(differences);
  const variance = differences.length < 2 ? 0 : differences.reduce((sum, value) => sum + (value - average) ** 2, 0) / (differences.length - 1);
  const standardDeviation = Math.sqrt(variance);
  return {
    meanDifference: average,
    cohenDz: standardDeviation === 0 ? (average === 0 ? 0 : null) : average / standardDeviation,
    ci95: pairedBootstrap(differences, 10000, 0x45a1e02b)
  };
}

function passK(groups, k) {
  const complete = groups.filter((group) => group.length >= k && group.slice(0, k).every(Boolean)).length;
  return groups.length === 0 ? null : complete / groups.length;
}

function conditionSummary(runs) {
  const latency = runs.map((run) => run.latencyMs);
  const tokenCounts = runs.map((run) => run.tokensProxy);
  const groups = new Map();
  for (const run of runs) {
    if (!groups.has(run.caseId)) groups.set(run.caseId, []);
    groups.get(run.caseId).push(run.success);
  }
  const groupValues = [...groups.values()];
  return {
    cases: groupValues.length,
    repetitions: groupValues.length === 0 ? 0 : groupValues[0].length,
    successRate: mean(runs.map((run) => Number(run.success))),
    passAtK: Object.fromEntries([1, 2, 3].map((k) => [String(k), passK(groupValues, k)])),
    latencyMs: { p50: quantile(latency, 0.5), p95: quantile(latency, 0.95) },
    tokensProxy: { p50: quantile(tokenCounts, 0.5), p95: quantile(tokenCounts, 0.95) },
    falseInterceptions: runs.filter((run) => run.falseInterception).length,
    safetyViolations: runs.filter((run) => run.safetyViolation).length
  };
}

function validateFixture(fixture) {
  assert(fixture && typeof fixture === 'object', 'fixture must be an object');
  assert(fixture.cases?.length >= 20, 'fixture must contain at least 20 cases');
  assert(fixture.repetitions >= 3, 'fixture must contain at least 3 repetitions');
  assert(fixture.seed !== undefined && Number.isInteger(fixture.seed), 'fixture seed must be an integer');
  assert(fixture.preregistration?.primaryMetric, 'fixture must preregister a primary metric');
  assert(fixture.preregistration?.regressionBudget, 'fixture must preregister a regression budget');
  const ids = new Set();
  for (const item of fixture.cases) {
    assert(typeof item.id === 'string' && item.id.length > 0, 'every case needs an id');
    assert(!ids.has(item.id), `duplicate case id: ${item.id}`);
    ids.add(item.id);
    assert(typeof item.expected === 'string', `case ${item.id} needs expected output`);
    assert(typeof item.response === 'string', `case ${item.id} needs a deterministic local response`);
  }
}

/**
 * Runs one isolated real RuntimeMemoryStore per condition and repetition.
 *
 * `runtimeFactory` must return the repository's production RuntimeMemoryStore.
 * `execute` receives that store and must perform the case without a provider or
 * network call. The policy adapter is deliberately injected so this evaluator
 * never owns product defaults, approval, or lock state.
 */
export async function runPairedAblation(options) {
  const {
    runtimeFactory,
    execute,
    fixture = await loadFixture(),
    bootstrapIterations = 10000
  } = options ?? {};
  assert(typeof runtimeFactory === 'function', 'runtimeFactory must construct the real RuntimeMemoryStore');
  assert(typeof execute === 'function', 'execute must implement the deterministic local case');
  validateFixture(fixture);

  const results = { baseline: [], treatment: [] };
  const retained = { baseline: [], treatment: [] };
  for (const condition of CONDITIONS) {
    for (let repetition = 0; repetition < fixture.repetitions; repetition += 1) {
      for (const item of fixture.cases) {
        const store = runtimeFactory({ condition, repetition, caseId: item.id });
        assert(store && store.constructor?.name === 'RuntimeMemoryStore', 'runtimeFactory must return RuntimeMemoryStore');
        const started = performance.now();
        const output = await execute({ store, condition, repetition, case: item, fixture });
        const latencyMs = performance.now() - started;
        assert(typeof output?.text === 'string', 'execute must return text');
        const success = output.text === item.expected;
        const falseInterception = Boolean(output.falseInterception);
        const safetyViolation = Boolean(output.safetyViolation);
        results[condition].push({
          caseId: item.id,
          repetition,
          success,
          falseInterception,
          safetyViolation,
          latencyMs,
          tokensProxy: tokenProxy(output.text)
        });
        retained[condition].push({
          caseId: item.id,
          repetition,
          keys: Array.isArray(output.retainedKeys) ? [...output.retainedKeys].sort() : null
        });
      }
    }
  }

  const pairs = fixture.cases.map((item) => {
    const byCondition = Object.fromEntries(CONDITIONS.map((condition) => {
      const runs = results[condition].filter((run) => run.caseId === item.id);
      return [condition, {
        success: mean(runs.map((run) => Number(run.success))),
        latencyMs: mean(runs.map((run) => run.latencyMs)),
        tokensProxy: mean(runs.map((run) => run.tokensProxy)),
        falseInterception: runs.some((run) => run.falseInterception),
        safetyViolation: runs.some((run) => run.safetyViolation)
      }];
    }));
    return { caseId: item.id, ...byCondition };
  });

  const primary = fixture.preregistration.primaryMetric;
  const metricFor = (pair) => {
    if (primary === 'successRate') return pair.treatment.success - pair.baseline.success;
    if (primary === 'latencyMs') return pair.treatment.latencyMs - pair.baseline.latencyMs;
    if (primary === 'tokensProxy') return pair.treatment.tokensProxy - pair.baseline.tokensProxy;
    throw new Error(`unsupported primary metric: ${primary}`);
  };
  const metricDifferences = pairs.map(metricFor);
  const componentChanged = retained.baseline.some((entry, index) => JSON.stringify(entry.keys) !== JSON.stringify(retained.treatment[index]?.keys));

  return {
    schemaVersion: 1,
    fixtureId: fixture.id,
    seed: fixture.seed,
    cases: fixture.cases.length,
    repetitions: fixture.repetitions,
    conditions: Object.fromEntries(CONDITIONS.map((condition) => [condition, conditionSummary(results[condition])])),
    paired: {
      primaryMetric: primary,
      effect: effect(metricDifferences),
      successEffect: effect(pairs.map((pair) => pair.treatment.success - pair.baseline.success)),
      latencyEffect: effect(pairs.map((pair) => pair.treatment.latencyMs - pair.baseline.latencyMs)),
      tokensEffect: effect(pairs.map((pair) => pair.treatment.tokensProxy - pair.baseline.tokensProxy)),
      falseInterceptions: {
        baseline: conditionSummary(results.baseline).falseInterceptions,
        treatment: conditionSummary(results.treatment).falseInterceptions,
        difference: conditionSummary(results.treatment).falseInterceptions - conditionSummary(results.baseline).falseInterceptions
      },
      safetyViolations: {
        baseline: conditionSummary(results.baseline).safetyViolations,
        treatment: conditionSummary(results.treatment).safetyViolations,
        difference: conditionSummary(results.treatment).safetyViolations - conditionSummary(results.baseline).safetyViolations
      }
    },
    componentChanged,
    preregistration: fixture.preregistration,
    decision: componentChanged && metricDifferences.some((value) => value !== 0)
      ? 'report-only; no product-default, lock, or approval change'
      : 'inconclusive-or-no-effect; report-only; no product-default, lock, or approval change'
  };
}

export async function loadFixture(path = DEFAULT_FIXTURE) {
  return JSON.parse(await readFile(path, 'utf8'));
}

export const metrics = Object.freeze({ conditionSummary, effect, passK, quantile, tokenProxy });
